import logoSizes from './logo-sizes.json'

/**
 * Intrinsic [width, height] of a topic logo or flag image, generated by
 * scripts/generate-logo-sizes.mjs; undefined for images it does not know (e.g. remote URLs).
 * Lets an <img> reserve its width before the image arrives, so the layout does not jump.
 */
export function intrinsicLogoSize(logoUrl: string | null | undefined): readonly [number, number] | undefined {
  if (!logoUrl) return undefined
  const key = logoUrl.replace(/^.*?assets\/images\//, '')
  const size = (logoSizes as Record<string, number[]>)[key]
  return size?.length === 2 ? [size[0], size[1]] : undefined
}
